/* Website support records are separate from property repair jobs. Demo delivery is browser-local. */
const normaliseBeforeWebsiteIssues=normalise;
normalise=function(){normaliseBeforeWebsiteIssues();state.websiteIssues??=[]};
const websiteIssueStates=['New','Investigating','Fixed','Closed'];
function websiteIssueContext(){const a=state.agencies.find(a=>a.id===agency),j=modal.open&&dialogRoute?.type==='job'?getJob(dialogRoute.jid):null;return {page:view,role,agency:a?.name||'Before agency registration',jobReference:j?.ref||'',browser:typeof navigator!=='undefined'?navigator.userAgent.slice(0,300):'Unknown',release:'Sevlink workspace · October 2026'}}
function reportWebsiteIssueForm(){if(typeof phoneMenu==='function')phoneMenu(false);const context=websiteIssueContext();openForm('Report a website issue.',`<div class="notice">Use this for a website bug or something that is not working. Property repairs belong under Report a repair.<br><b>Page:</b> ${esc(context.page)} · <b>View:</b> ${esc(context.role)}${context.jobReference?'<br>Job reference: '+esc(context.jobReference):''}</div><label>Short summary</label><input name="summary" required maxlength="160" placeholder="e.g. Payment record will not save"><label>What went wrong?</label><textarea name="description" required rows="4" maxlength="4000" placeholder="What did you try to do, what happened, and what did you expect?"></textarea><label>Steps to repeat the problem (optional)</label><textarea name="steps" rows="3" maxlength="3000" placeholder="e.g. Open job → Invoices → Save payment"></textarea><label>How much is it affecting you?</label><select name="impact"><option value="Minor">Minor · I can continue working</option><option value="Disruptive">Disruptive · some tasks do not work</option><option value="Blocking">Blocking · I cannot continue</option></select><label>Contact email (optional)</label><input name="email" type="email" maxlength="254" placeholder="For a follow-up"><label>Screenshot (optional · JPG, PNG or WebP, up to 5 MB)</label><input name="screenshot" type="file" accept="image/jpeg,image/png,image/webp"><small>Check the screenshot for private information before attaching it.</small><div class="notice">The page, role and browser details are included to help investigate. This demo saves the report in this browser, where Sevlink Operations can review it. No email is sent.</div>`,'Log website issue',async data=>{let screenshot;try{screenshot=await fileData(data.get('screenshot'),imageTypes)}catch(e){toast(e.message);return}const result=await saveWebsiteIssue({summary:data.get('summary'),description:data.get('description'),steps:data.get('steps'),impact:data.get('impact'),email:data.get('email'),screenshot,context});if(result){modal.close();render();toast(result.ref+' logged. Thank you for reporting the problem.')}})}
async function saveWebsiteIssue(data){if(!state||!['manager','tenant','sevlink'].includes(role))return false;const summary=String(data.summary||'').trim(),description=String(data.description||'').trim();if(!summary||summary.length>160||!description||description.length>4000||!['Minor','Disruptive','Blocking'].includes(data.impact))return false;const context=data.context||websiteIssueContext(),ref='WEB-'+String(1+Math.max(0,...(state.websiteIssues||[]).map(i=>Number(i.number)||0))).padStart(4,'0');let issue;const saved=await commit(()=>{state.websiteIssues??=[];issue={id:id('web'),number:Number(ref.slice(4)),ref,summary,description,steps:String(data.steps||'').trim().slice(0,3000),impact:data.impact,email:String(data.email||'').trim().slice(0,254),screenshot:data.screenshot||null,context:{page:context.page,role:context.role,agency:context.agency,jobReference:context.jobReference,browser:context.browser,release:context.release},status:'New',createdAt:now(),log:[{at:now(),status:'New',note:'Website issue reported.'}]};state.websiteIssues.unshift(issue)});return saved?issue:false}
let websiteIssueFilter='Open',websiteIssueSearch='';
function visibleWebsiteIssues(){if(role!=='sevlink')return [];return (state.websiteIssues||[]).filter(i=>(websiteIssueFilter==='All'||websiteIssueFilter==='Open'&&!['Fixed','Closed'].includes(i.status)||websiteIssueFilter===i.status)&&`${i.ref} ${i.summary} ${i.description} ${i.context.agency}`.toLowerCase().includes(websiteIssueSearch.toLowerCase()))}
function renderWebsiteIssueRows(){const target=$('#websiteIssueRows');if(!target||role!=='sevlink')return;target.innerHTML=visibleWebsiteIssues().map(i=>`<button class="website-issue-row" onclick="websiteIssueDetail('${i.id}')"><span class="eyebrow">${i.ref} · ${esc(i.impact)}</span><strong>${esc(i.summary)}</strong><span>${esc(i.context.agency)} · ${esc(i.context.page)} · ${esc(i.context.role)}</span><small>${date(i.createdAt)} · ${esc(i.status)}</small></button>`).join('')||'<p>No website issues match this filter.</p>'}
function renderWebsiteIssues(){if(role!=='sevlink'){app.innerHTML=heading('Sevlink staff access required.','Website issue records are managed by Sevlink Operations.');return}const issues=state.websiteIssues||[];app.innerHTML=heading('Website issues.','Track reported bugs separately from property maintenance.','<button class="primary" onclick="reportWebsiteIssueForm()">＋ Log website issue</button>')+`<div class="notice">Browser-local demo reports. No automatic email or cross-device delivery is connected.</div><div class="stats">${websiteIssueStates.map(status=>`<div class="stat"><label>${status}</label><strong>${issues.filter(i=>i.status===status).length}</strong></div>`).join('')}</div><div class="panel" style="margin-top:22px"><div class="filters"><input id="websiteIssueSearch" type="search" placeholder="Search reference, problem or agency…" aria-label="Search website issues" value="${esc(websiteIssueSearch)}"><select id="websiteIssueFilter" aria-label="Filter website issues">${['Open','All',...websiteIssueStates].map(status=>`<option ${status===websiteIssueFilter?'selected':''}>${status}</option>`).join('')}</select></div><div id="websiteIssueRows"></div></div>`;renderWebsiteIssueRows();$('#websiteIssueSearch').oninput=e=>{websiteIssueSearch=e.target.value;renderWebsiteIssueRows()};$('#websiteIssueFilter').onchange=e=>{websiteIssueFilter=e.target.value;renderWebsiteIssueRows()}}
function websiteIssueDetail(iid){if(role!=='sevlink')return;const i=state.websiteIssues.find(i=>i.id===iid);if(!i)return;modal.innerHTML=`<button class="close" onclick="modal.close()" aria-label="Close">×</button><span class="eyebrow">WEBSITE SUPPORT · ${i.ref}</span><h1>${esc(i.summary)}</h1>${badge(i.status)} ${badge(i.impact)}<p>${date(i.createdAt)}<br>${esc(i.context.agency)} · ${esc(i.context.role)}<br>Page: ${esc(i.context.page)}${i.context.jobReference?'<br>Job: '+esc(i.context.jobReference):''}${i.email?'<br>Contact: '+esc(i.email):''}</p><h2>What went wrong</h2><p style="white-space:pre-wrap">${esc(i.description)}</p><h2>Steps to reproduce</h2><p style="white-space:pre-wrap">${esc(i.steps||'Not supplied.')}</p>${i.screenshot?`<h2>Attached screenshot</h2><img src="${i.screenshot.data}" alt="Screenshot supplied with website issue" style="width:100%;max-height:420px;object-fit:contain;border:1px solid var(--line);border-radius:8px">`:''}<details class="notice"><summary>Technical context</summary><p>${esc(i.context.browser)}<br>${esc(i.context.release)}</p></details><form id="websiteIssueStatusForm"><label>Status</label><select name="status">${websiteIssueStates.map(s=>`<option ${i.status===s?'selected':''}>${s}</option>`).join('')}</select><label>Investigation / resolution note</label><textarea name="note" required rows="3" maxlength="2000" placeholder="Record the investigation or what was fixed."></textarea><div class="actions"><button class="primary" type="submit">Save status update</button><button class="secondary" id="downloadWebsiteIssue" type="button">Download issue record</button></div></form><h2 style="margin-top:22px">Issue history</h2>${i.log.map(l=>`<div class="activity"><b>${esc(l.status)}</b> · ${esc(l.note)}<small>${date(l.at)}${l.by?' · '+esc(l.by):''}</small></div>`).join('')}`;if(!modal.open)modal.showModal();$('#websiteIssueStatusForm').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);if(await updateWebsiteIssue(iid,data.get('status'),data.get('note'))){render();websiteIssueDetail(iid);toast('Website issue updated.')}};$('#downloadWebsiteIssue').onclick=()=>downloadWebsiteIssue(iid)}
async function updateWebsiteIssue(iid,status,note){if(role!=='sevlink'||!websiteIssueStates.includes(status)||!String(note||'').trim())return false;const issue=state.websiteIssues.find(i=>i.id===iid);if(!issue)return false;return commit(()=>{issue.status=status;issue.updatedAt=now();issue.log.push({at:now(),status,note:String(note).trim().slice(0,2000),by:person()})})}
function downloadWebsiteIssue(iid){if(role!=='sevlink')return;const issue=state.websiteIssues.find(i=>i.id===iid);if(!issue)return;const blob=new Blob([JSON.stringify(issue,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=issue.ref+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const renderBeforeWebsiteIssues=render;
render=function(){renderBeforeWebsiteIssues();if(!state)return;$('#nav').insertAdjacentHTML('beforeend',`${role==='sevlink'?`<button data-view="websiteissues" class="${view==='websiteissues'?'active':''}">⚑ &nbsp; Website issues <small>${(state.websiteIssues||[]).filter(i=>!['Fixed','Closed'].includes(i.status)).length}</small></button>`:''}<button onclick="reportWebsiteIssueForm()" class="website-issue-report">⚑ &nbsp; Report website issue</button>`);if(view==='websiteissues')renderWebsiteIssues()};
